/** Normalize typography, not historical identities: never use approximate fuzzy matching. */
export const normalizeHistoricalReferenceName=(s:string)=>s.normalize("NFKC").toLocaleLowerCase("ru-RU")
 .replace(/[’‘ʼ'`´]/g,"").replace(/[‐‑‒–—−_-]/g," ")
 .replace(/[.,;:!?()[\]{}]/g," ").replace(/\s+/g," ").trim();
// Build a lookup once. It is shared by map labels, period navigation and the
// encyclopedia: adding more articles must not turn every polygon render into
// a linear scan of the entire reference catalogue.
const historicalReferenceByAlias=(()=>{
 const index=new Map<string,HistoricalReference[]>();
 for(const entry of historicalReferences){
  for(const alias of new Set([entry.title,...entry.aliases].map(normalizeHistoricalReferenceName))){
   if(!alias)continue;
   const matches=index.get(alias);
   if(matches)matches.push(entry);
   else index.set(alias,[entry]);
  }
 }
 return index;
})();
export function findHistoricalReference(name:string,year:number):HistoricalReference|undefined{
 const key=normalizeHistoricalReferenceName(name);
 if(!key||year===2026)return undefined;
 return historicalReferenceByAlias.get(key)?.find(entry=>year>=entry.from&&year<=entry.to);
}
